using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Media3D;
using System.Windows.Threading;
namespace FrameScout {
 public static class ScrollInteractions {
  static bool installed;static PanSession pan;
  sealed class PanSession {public Window Window;public ScrollViewer Viewer;public Point Anchor,Current;public double StartX,StartY,TargetX,TargetY;public bool Dragged,Latched;public Cursor PreviousCursor;public DispatcherTimer Timer;public DateTime LastTick;}
  public static void Install(){if(installed)return;installed=true;EventManager.RegisterClassHandler(typeof(Window),UIElement.PreviewMouseWheelEvent,new MouseWheelEventHandler(OnWheel),true);EventManager.RegisterClassHandler(typeof(Window),UIElement.PreviewMouseDownEvent,new MouseButtonEventHandler(OnDown),true);EventManager.RegisterClassHandler(typeof(Window),UIElement.PreviewMouseMoveEvent,new MouseEventHandler(OnMove),true);EventManager.RegisterClassHandler(typeof(Window),UIElement.PreviewMouseUpEvent,new MouseButtonEventHandler(OnUp),true);EventManager.RegisterClassHandler(typeof(Window),UIElement.LostMouseCaptureEvent,new MouseEventHandler((s,e)=>{if(pan!=null&&pan.Window==s&&Mouse.Captured!=s)EndPan();}),true);EventManager.RegisterClassHandler(typeof(Window),UIElement.PreviewKeyDownEvent,new KeyEventHandler((s,e)=>{if(pan!=null&&pan.Window==s){EndPan();if(e.Key==Key.Escape)e.Handled=true;}}),true);}
  static DependencyObject Parent(DependencyObject value){if(value is Visual||value is Visual3D)return VisualTreeHelper.GetParent(value);var content=value as FrameworkContentElement;if(content!=null)return content.Parent;return LogicalTreeHelper.GetParent(value);}
  static bool Usable(ScrollViewer viewer,bool horizontal){return viewer!=null&&(viewer.ScrollableWidth>.01||!horizontal&&viewer.ScrollableHeight>.01);}
  static ScrollViewer Inside(DependencyObject node,bool horizontal){if(!(node is Visual)&&!(node is Visual3D))return null;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++){var child=VisualTreeHelper.GetChild(node,i);var viewer=child as ScrollViewer;if(Usable(viewer,horizontal))return viewer;var nested=Inside(child,horizontal);if(nested!=null)return nested;}return null;}
  public static ScrollViewer FindViewer(DependencyObject origin,bool horizontalOnly=false){for(var p=origin;p!=null;p=Parent(p)){var viewer=p as ScrollViewer;if(Usable(viewer,horizontalOnly))return viewer;if(p is DataGrid||p is System.Windows.Controls.Primitives.TextBoxBase||p is ItemsControl){var nested=Inside(p,horizontalOnly);if(nested!=null)return nested;}}return null;}
  static double Scale(ScrollViewer viewer,bool horizontal){if(!viewer.CanContentScroll)return 1;viewer.ApplyTemplate();var host=viewer.Template.FindName("PART_ScrollContentPresenter",viewer) as FrameworkElement;double pixels=host==null?(horizontal?viewer.ActualWidth:viewer.ActualHeight):(horizontal?host.ActualWidth:host.ActualHeight);double viewport=horizontal?viewer.ViewportWidth:viewer.ViewportHeight;return pixels>0&&viewport>0?viewport/pixels:1;}
  static double Clamp(double value,double max){return Math.Max(0,Math.Min(Math.Max(0,max),value));}
  public static bool ScrollHorizontal(DependencyObject origin,double wheelDelta){var viewer=FindViewer(origin,true);if(viewer==null)return false;viewer.ScrollToHorizontalOffset(Clamp(viewer.HorizontalOffset-wheelDelta/120.0*72*Scale(viewer,true),viewer.ScrollableWidth));return true;}
  static void OnWheel(object sender,MouseWheelEventArgs e){if(pan!=null)EndPan();if((Keyboard.Modifiers&ModifierKeys.Shift)!=0){bool moved=ScrollHorizontal(e.OriginalSource as DependencyObject,e.Delta);if(moved||FindViewer(e.OriginalSource as DependencyObject)!=null)e.Handled=true;}}
  static void OnDown(object sender,MouseButtonEventArgs e){if(pan!=null){EndPan();e.Handled=true;return;}if(e.ChangedButton!=MouseButton.Middle||Mouse.LeftButton==MouseButtonState.Pressed||Mouse.RightButton==MouseButtonState.Pressed)return;var window=(Window)sender;var viewer=FindViewer(e.OriginalSource as DependencyObject);if(viewer==null)return;if(BeginPan(window,viewer,Mouse.GetPosition(window)))e.Handled=true;}
  static bool BeginPan(Window window,ScrollViewer viewer,Point point){EndPan();var state=new PanSession{Window=window,Viewer=viewer,Anchor=point,Current=point,StartX=viewer.HorizontalOffset,StartY=viewer.VerticalOffset,TargetX=viewer.HorizontalOffset,TargetY=viewer.VerticalOffset,PreviousCursor=Mouse.OverrideCursor};pan=state;if(!Mouse.Capture(window,CaptureMode.SubTree)){pan=null;return false;}Mouse.OverrideCursor=Cursors.ScrollAll;window.Deactivated+=Deactivate;window.Closed+=Close;state.Timer=new DispatcherTimer(DispatcherPriority.Input,window.Dispatcher){Interval=TimeSpan.FromMilliseconds(20)};state.Timer.Tick+=(s,e)=>Tick();return true;}
  static void Deactivate(object s,EventArgs e){EndPan();}static void Close(object s,EventArgs e){EndPan();}
  static void OnMove(object sender,MouseEventArgs e){if(pan==null||pan.Window!=sender)return;MovePan(Mouse.GetPosition(pan.Window),e.MiddleButton==MouseButtonState.Pressed);e.Handled=true;}
  static void MovePan(Point point,bool middlePressed){if(pan==null)return;pan.Current=point;if(pan.Latched)return;double dx=point.X-pan.Anchor.X,dy=point.Y-pan.Anchor.Y;if(middlePressed&&(Math.Abs(dx)>4||Math.Abs(dy)>4))pan.Dragged=true;if(pan.Dragged&&middlePressed){pan.TargetX=Clamp(pan.StartX-dx*Scale(pan.Viewer,true),pan.Viewer.ScrollableWidth);pan.TargetY=Clamp(pan.StartY-dy*Scale(pan.Viewer,false),pan.Viewer.ScrollableHeight);ApplyPan();}}
  static void OnUp(object sender,MouseButtonEventArgs e){if(pan==null||pan.Window!=sender||e.ChangedButton!=MouseButton.Middle)return;ReleasePan();e.Handled=true;}
  static void ReleasePan(){if(pan==null)return;if(pan.Dragged){EndPan();return;}pan.Latched=true;pan.LastTick=DateTime.UtcNow;pan.Timer.Start();}
  static double Velocity(double distance){double d=Math.Abs(distance)-14;return d<=0?0:Math.Sign(distance)*Math.Min(1200,Math.Pow(d,1.2)*3);}
  static void Tick(){if(pan==null||!pan.Latched)return;double dt=Math.Max(.001,Math.Min(.1,(DateTime.UtcNow-pan.LastTick).TotalSeconds));pan.LastTick=DateTime.UtcNow;pan.TargetX=Clamp(pan.TargetX+Velocity(pan.Current.X-pan.Anchor.X)*dt*Scale(pan.Viewer,true),pan.Viewer.ScrollableWidth);pan.TargetY=Clamp(pan.TargetY+Velocity(pan.Current.Y-pan.Anchor.Y)*dt*Scale(pan.Viewer,false),pan.Viewer.ScrollableHeight);ApplyPan();}
  static void ApplyPan(){if(pan==null)return;pan.Viewer.ScrollToHorizontalOffset(pan.TargetX);pan.Viewer.ScrollToVerticalOffset(pan.TargetY);}
  public static void EndPan(){var old=pan;if(old==null)return;pan=null;if(old.Timer!=null)old.Timer.Stop();old.Window.Deactivated-=Deactivate;old.Window.Closed-=Close;if(Mouse.Captured==old.Window)Mouse.Capture(null);Mouse.OverrideCursor=old.PreviousCursor;}
 }
}
